import{_ as t,o,c as s,aj as r}from"./chunks/framework.DdvcgEK0.js";const m=JSON.parse('{"title":"How it works","description":"","frontmatter":{},"headers":[],"relativePath":"guide/how-it-works.md","filePath":"guide/how-it-works.md"}'),a={name:"guide/how-it-works.md"};function i(d,e,n,c,h,l){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h1><h2 id="the-smart-score" tabindex="-1">The <code>smart</code> score <a class="header-anchor" href="#the-smart-score" aria-label="Permalink to &quot;The `smart` score&quot;">​</a></h2><ol><li><strong>Normalize</strong> both texts: lower case, no accents, no punctuation, single spaces, plus your <code>strip</code>, <code>replace</code> and <code>ignoreWords</code>.</li><li><strong>Characters</strong>: Damerau-Levenshtein distance, turned into a score with <code>(1 - distance / longest length) × 100</code>. A swapped pair of letters (<code>teh</code> / <code>the</code>) counts as a single typo.</li><li><strong>Word order</strong> (<code>ignoreWordOrder</code>): the same, with words sorted.</li><li><strong>Spaces</strong> (<code>ignoreSpaces</code>): the same, with spaces removed.</li><li><strong>Partial</strong> (<code>partial</code>): the shorter text is matched against the start of any word of the longer one, or word by word in any order. The result is weighted by how much of the longer text it covers, with a bonus when the match is at the very start, so a full match always ranks first and <code>i don</code> prefers <code>I Don&#39;t Care</code> over <code>Til I Don&#39;t</code>. In lists, only the query can be the partial side.</li></ol><p>The final score is the best of these. <code>compare()</code> shows each of them:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">compare</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Smith Jon&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;John Smith&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// { score: 90, a: &#39;smith jon&#39;, b: &#39;john smith&#39;, scores: { characters: 10, wordOrder: 90 }, ... }</span></span></code></pre></div><h2 id="algorithms" tabindex="-1">Algorithms <a class="header-anchor" href="#algorithms" aria-label="Permalink to &quot;Algorithms&quot;">​</a></h2><p><code>smart</code> is right for almost everything. The others exist for specific needs:</p><table tabindex="0"><thead><tr><th><code>algorithm</code></th><th>Use when</th></tr></thead><tbody><tr><td><code>smart</code></td><td>Default.</td></tr><tr><td><code>damerau</code></td><td>Order and spaces matter, swapped letters count once.</td></tr><tr><td><code>levenshtein</code></td><td>You need the textbook edit distance.</td></tr><tr><td><code>jaroWinkler</code></td><td>Short strings where the beginning matters most, such as names.</td></tr><tr><td><code>tokenSort</code></td><td>Only word order should be ignored.</td></tr><tr><td><code>tokenSet</code></td><td>Extra words should not matter: a subset scores 100.</td></tr></tbody></table><p>The raw distances are exported too, without normalization: <code>levenshtein(a, b)</code>, <code>damerau(a, b)</code> and <code>jaroWinkler(a, b)</code>.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><ul><li>Distances use bit-parallel algorithms (Myers, Hyyrö) for texts up to 32 characters, and skip common prefixes and suffixes.</li><li>Options are compiled once per <code>createMatcher()</code>, <code>createIndex()</code>, or options object you reuse.</li><li>List functions normalize the query once, then rule out most candidates with cheap upper bounds (lengths, character counts, one bit-parallel scan) before computing any distance.</li><li>With <code>limit</code>, the bar rises to the score of the worst kept result, so even fewer candidates are scored.</li><li><code>createIndex()</code> normalizes the list once; each search only scores the query.</li></ul><p>Measured with <code>npm run bench:real</code> on public datasets: see the <a href="/guess-rater/#try-it">home page</a> or the README.</p><p>Run <code>npm run bench</code> in the repository to measure on your machine.</p>',13)])])}const u=t(a,[["render",i]]);export{m as __pageData,u as default};
